input.command:
cd /private/tmp/claude-501/-Users-matteodospina-orca-workspaces-vela-doc-m10/a708c644-423d-419b-9cd6-1af5d89fd32e/scratchpad && PYTHONPATH=/Users/matteodospina/orca/workspaces/vela/doc-m10 python3 - <<'EOF'
import json,glob
from vela.domain.catalog import detect_sport
for f in sorted(glob.glob('brand-ids/*/*products*.json')):
    for p in json.load(open(f))['body']['data']:
        if p.get('archived'): continue
        t=(p.get('title') or '')+' '+(p.get('slug') or '')+' '+(p.get('shortDescription') or '')
        if detect_sport(p.get('title'),p.get('slug'),p.get('shortDescription'))=='padel':
            print(f.split('/')[1], p['id'], repr(p.get('title')), 'padel' in t.lower())
EOF

